<span class="line"><span style="color:#61AFEF;">    TsFileTableWriter</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">WriteFile</span><span style="color:#C678DD;">*</span><span style="color:#E06C75;font-style:italic;"> writer_file</span><span style="color:#ABB2BF;">,</span></span>
